  "a_sentences": [
    {
      "a_text": "La personne assurée critique le choix de l'assureur de résilier le bail, alors qu'elle occupe le logement depuis plus de 30 ans, tout en laissant d'autres locataires dans l'immeuble voisin.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Lorsque les parties sont représentées par un avocat, le tribunal doit faire preuve de retenue, comme dans un procès ordinaire.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Chaque partie peut résilier un bail de durée indéterminée pour la prochaine échéance contractuelle en respectant le délai de congé.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "La motivation du congé n'est pas une condition de sa validité et son absence ne signifie pas nécessairement qu'il est contraire à la bonne foi.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Le congé contrevient aux règles de la bonne foi lorsqu'il consacre une disproportion crasse entre l'intérêt du locataire au maintien du contrat et celui du bailleur à y mettre fin.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "La juridiction cantonale a constaté que le congé adressé à la personne assurée ne donnait pas de motif de résiliation.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "La juridiction cantonale a retenu que la résiliation n'entraînait pas de conséquences particulièrement pénibles pour la personne assurée.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral confirme que l'intérêt de l'actionnaire de l'assureur à mettre le logement à disposition de son fils, âgé de 25 ans, n'est ni futile ni ridicule et ne consacre pas une disproportion crasse des intérêts.",
      "b_propositions": ["P8"]
    }
  ]
}
